-- ============================================
-- TIPOS_DOCUMENTO: tipos de documento de la pregunta (Oficio, Memorando...) y de la
-- respuesta de la ORAJ (Informe Legal, Opinión Legal, Oficio...).
-- USO_RESPUESTA / USO_SOLICITUD: en qué lista aparece; ORDEN / ORDEN_SOLICITUD: posición
-- en cada lista (1 = primero, el más común).
-- PREFIJO arma el código: "<PREFIJO> N° 001-2026-<SIGLA_ORAJ>"
-- ============================================
CREATE TABLE IF NOT EXISTS "TIPOS_DOCUMENTO" (
    "ID_TIPO_DOCUMENTO" INT GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_TIPOS_DOCUMENTO" PRIMARY KEY,
    "NOMBRE" VARCHAR(100) NOT NULL CONSTRAINT "UQ_TIPOS_DOCUMENTO_NOMBRE" UNIQUE,
    "PREFIJO" VARCHAR(50) NOT NULL,
    "USO_RESPUESTA" BOOLEAN NOT NULL DEFAULT TRUE,
    "USO_SOLICITUD" BOOLEAN NOT NULL DEFAULT FALSE,
    "ORDEN" INT NOT NULL DEFAULT 50,
    "ORDEN_SOLICITUD" INT NOT NULL DEFAULT 50,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "CHK_TIPOS_DOCUMENTO_USO" CHECK ("USO_RESPUESTA" OR "USO_SOLICITUD"),
    CONSTRAINT "CHK_TIPOS_DOCUMENTO_ORDEN" CHECK ("ORDEN" >= 0 AND "ORDEN_SOLICITUD" >= 0)
);
